/** Position 2 (upside down) is reached at ARRIVE; the recording held it until HOLD_END. */
const ARRIVE = 4.118, HOLD_END = 4.468
/** How far the fingers close when they contract (0 = as recorded, 1 = a full fist). */
const CONTRACT = .3
const FIST: Record<string, number[]> = { thumb: [.5, .48, .25], index: [1.25, 1.45, .9], middle: [1.25, 1.45, .9], ring: [1.25, 1.45, .9], pinky: [1.25, 1.45, .9] }
const arrived = keys.find(([time]) => Math.abs(time - ARRIVE) < 1e-6)!
/** Position 2 exactly as recorded: the hand stays here (same wrist, direction and palm) while the fingers move. */
const open = arrived[1] as RecordedArm, base = arrived[2] as RecordedArm
/** The thumb moves with the fingers: it bends in toward the palm and turns a little toward the fingers. */
const THUMB_BEND = [.35, .35, .25], THUMB_TURN = .3
const fingersIn = Object.fromEntries(Object.entries(open.c).map(([digit, joints]) => [digit, joints.map((x, j) => +(x + CONTRACT * (FIST[digit][j] - x)).toFixed(3))])) as RecordedArm['c']
const contracted: RecordedArm = {
  ...open,
  c: { ...fingersIn, thumb: open.c.thumb.map((x, j) => +(x + THUMB_BEND[j]).toFixed(3)) },
  o: Math.min(1, open.o + THUMB_TURN),
}
/** Fingers: contract, open, contract, open (0.2 s each way). */
const contractions: RecordedKey[] = [[4.318, contracted, base], [4.518, open, base], [4.718, contracted, base], [4.918, open, base]]
const CONTRACTIONS_SHIFT = 4.918 - HOLD_END
const withContractions: RecordedKey[] = [
  ...keys.filter(([time]) => time <= ARRIVE + 1e-6), // rise, position 1, turn over, arrive upside down
  ...contractions,
  ...keys.filter(([time]) => time > HOLD_END + 1e-6).map(([time, right, left]): RecordedKey => [+(time + CONTRACTIONS_SHIFT).toFixed(3), right, left]),
]

/**
 * Shorter position 1: the hand now arrives upside down at 3.0 s instead of 4.118 s. Only the
 * position-1 hold (recorded 0.835 – 3.223 s) is compacted; the rise and the turn over keep their
 * recorded speed, and everything after it moves earlier by the same amount.
 */
const P1_START = .835, P1_END = 3.223, NEW_ARRIVE = 3.0
const SAVED = ARRIVE - NEW_ARRIVE, P1_NEW_END = P1_END - SAVED
const retime = (time: number) => time <= P1_START ? time
  : time <= P1_END ? P1_START + (time - P1_START) * (P1_NEW_END - P1_START) / (P1_END - P1_START)
  : time - SAVED
export const TANINTHARYI_DURATION = +(RECORDED_DURATION + CONTRACTIONS_SHIFT - SAVED).toFixed(2)
const edited: RecordedKey[] = withContractions.map(([time, right, left]): RecordedKey => [+retime(time).toFixed(3), right, left])

export function createTanintharyiAnimation(model: Object3D) {
  // Mirrored: played on the character's right hand (a two-handed sign swaps hands).
  return createRecordedClip(model, mirrorKeys(edited), TANINTHARYI_DURATION)
}
